+  match(Set dst (CMoveP (Binary cop (CmpI op1 op2)) (Binary dst src)));
+  match(Set dst (CMoveP (Binary cop (CmpL op1 op2)) (Binary dst src)));
+  ins_cost(ALU_COST + BRANCH_COST);
